// Command notes keeps a small list of notes in a JSON file.
//
//	notes add <text>     append a note
//	notes list           print notes with their ids
//	notes done <id>      mark a note done
package main

import (
	"fmt"
	"os"
	"strconv"
	"strings"
)

func main() {
	path := os.Getenv("NOTES_FILE")
	if path == "" {
		path = "notes.json"
	}
	store, err := Open(path)
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	if err := run(store, os.Args[1:]); err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(2)
	}
}

func run(store *Store, args []string) error {
	if len(args) == 0 {
		return fmt.Errorf("usage: notes add|list|done")
	}
	switch args[0] {
	case "add":
		n, err := store.Add(strings.Join(args[1:], " "))
		if err != nil {
			return err
		}
		fmt.Println(n.ID)
	case "list":
		for _, n := range store.List() {
			mark := " "
			if n.Done {
				mark = "x"
			}
			fmt.Printf("[%s] %d %s\n", mark, n.ID, n.Text)
		}
	case "done":
		if len(args) != 2 {
			return fmt.Errorf("usage: notes done <id>")
		}
		id, err := strconv.Atoi(args[1])
		if err != nil {
			return fmt.Errorf("id must be a number: %w", err)
		}
		return store.Done(id)
	default:
		return fmt.Errorf("unknown command %q", args[0])
	}
	return nil
}

