package main

import (
	"encoding/json"
	"errors"
	"fmt"
	"os"
)

// Note is one entry of the list.
type Note struct {
	ID   int    `json:"id"`
	Text string `json:"text"`
	Done bool   `json:"done"`
}

// Store persists notes as a JSON array in one file.
type Store struct {
	path  string
	notes []Note
}

// Open loads the file at path; a missing file is an empty store.
func Open(path string) (*Store, error) {
	s := &Store{path: path}
	b, err := os.ReadFile(path)
	if errors.Is(err, os.ErrNotExist) {
		return s, nil
	}
	if err != nil {
		return nil, err
	}
	if err := json.Unmarshal(b, &s.notes); err != nil {
		return nil, fmt.Errorf("%s: %w", path, err)
	}
	return s, nil
}

// Add appends a note with the next id and saves.
func (s *Store) Add(text string) (Note, error) {
	if text == "" {
		return Note{}, errors.New("note text is empty")
	}
	n := Note{ID: len(s.notes) + 1, Text: text}
	s.notes = append(s.notes, n)
	return n, s.save()
}

// List returns all notes in insertion order.
func (s *Store) List() []Note { return s.notes }

// Done marks the note with id as done and saves.
func (s *Store) Done(id int) error {
	for i := range s.notes {
		if s.notes[i].ID == id {
			s.notes[i].Done = true
			return s.save()
		}
	}
	return fmt.Errorf("no note %d", id)
}

func (s *Store) save() error {
	b, err := json.MarshalIndent(s.notes, "", "  ")
	if err != nil {
		return err
	}
	return os.WriteFile(s.path, b, 0o644)
}

