package main

import (
	"path/filepath"
	"testing"
)

func TestAddListDone(t *testing.T) {
	path := filepath.Join(t.TempDir(), "notes.json")
	s, err := Open(path)
	if err != nil {
		t.Fatal(err)
	}
	if _, err := s.Add("buy milk"); err != nil {
		t.Fatal(err)
	}
	if err := s.Done(1); err != nil {
		t.Fatal(err)
	}
	r, err := Open(path)
	if err != nil {
		t.Fatal(err)
	}
	got := r.List()
	if len(got) != 1 || !got[0].Done || got[0].Text != "buy milk" {
		t.Fatalf("got %+v", got)
	}
}

